atmospheric_composition_heuristic_js:
const atmosphericContext=(n)=>{
  const mid=(n.start+n.end)/2;
  if(n.id==='earth')return 'For most of Earth history, free atmospheric O₂ was scarce. Photosynthesis progressively oxygenated air and seas; CO₂, methane and water vapor drove large greenhouse shifts. Today O₂ is about 21% and CO₂ is rising from human activity.';
  if(mid>2500)return 'Little free atmospheric O₂; carbon dioxide, water vapor and possibly methane were key greenhouse gases. Precise abundances are poorly constrained.';
  if(mid>1000)return 'O₂ accumulated after the Great Oxidation Event but remained variable and often below modern levels. CO₂ and methane fluctuated; reconstructed values are uncertain.';
  if(mid>539)return 'Atmospheric and ocean oxygenation proceeded in stages; CO₂ and O₂ estimates differ among proxies and models.';
  if(mid>420)return 'Early Paleozoic atmospheric O₂ was probably below modern abundance for part of the interval; CO₂ was generally elevated but variable.';
  if(mid>300)return 'Vascular-plant expansion drew down CO₂ while O₂ rose; some Carboniferous reconstructions imply substantially more O₂ than today.';
  if(mid>252)return 'Late Paleozoic O₂ and CO₂ varied strongly with forests, coal burial, volcanism and end-Permian environmental disruption.';
  if(mid>145)return 'Predominantly greenhouse conditions with variable, often elevated CO₂; global O₂ reconstructions remain model-dependent.';
  if(mid>66)return 'Greenhouse CO₂ was generally elevated relative to preindustrial conditions, especially during warm Cretaceous intervals. O₂ values are less securely reconstructed.';
  if(mid>34)return 'Early Cenozoic greenhouse CO₂ declined over tens of millions of years toward the Antarctic glaciation threshold; O₂ was broadly comparable to modern levels.';
  if(mid>2.58)return 'Long-term CO₂ declined and fluctuated through the Neogene while modern-style atmospheric and ecological systems took shape.';
  return 'Quaternary ice-core records document glacial CO₂ near 180 ppm and preindustrial interglacial CO₂ near 280 ppm. Atmospheric O₂ today is about 21%; modern human-driven CO₂ is higher.';
};

paleomap_selection_render_js:
function continentMap(n){let mid=(n.start+n.end)/2,k=mid<8?'modern':mid<75?'ceno':mid<143?'cret':mid<235?'jur':mid<350?'perm':mid<560?'early':'old',m=MAP_SHAPES[k];let svg=`<svg viewBox="0 0 600 303" role="img" aria-label="${m.title}; generalized arrangement, not a scale reconstruction" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="oceanFill" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#123650"/><stop offset="1" stop-color="#071f33"/></linearGradient><linearGradient id="landFill" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#8cab6d"/><stop offset="1" stop-color="#385f58"/></linearGradient></defs><rect x="2" y="2" width="596" height="299" rx="18" fill="url(#oceanFill)"/><g stroke="#6a99b9" opacity=".18" fill="none"><path d="M2 76H598M2 151H598M2 227H598M102 2V301M200 2V301M299 2V301M399 2V301M499 2V301"/></g><g fill="url(#landFill)" stroke="#bbcea5" stroke-width="2">${m.land.map(d=>`<path d="${d}"/>`).join('')}</g><g fill="#e0f3e0" stroke="#12334b" stroke-width="3" paint-order="stroke" font-family="system-ui" font-weight="650" font-size="12">${m.label.map(([t,x,y])=>`<text x="${x}" y="${y}">${t}</text>`).join('')}</g></svg>`;
 return `<div class="paleoMap"><div class="mapHeading"><strong>${esc(m.title)}</strong><span>${m.age}</span></div>${svg}<p class="mapCaption">Simplified educational landmass diagram, <b>not a georeferenced plate reconstruction</b>. The closest representative time slice is shown; coastlines, sea levels and positions are approximate, especially in deep Precambrian time.</p></div>`;
}

taxon_popularity_and_interval_associatio:
const familiarOrder=['dinosaurs','tyrannosauroidea','mammalia','aves','angiosperms','hominini','primates','trilobita','arthropoda','insecta','pterosauria','ammonoidea','cetacea','theropoda','ceratopsia','crocodylia','squamata','fishes','sharks','mollusca','coniferophyta','poaceae','hymenoptera','lepidoptera','coleoptera','passeriformes','dromaeosauridae','ankylosauria','stegosauria','titanosauria','sauropoda','eutheria','rodentia','carnivora','tardigrada','bacteria','cyanobacteria','eukaryotes','foraminifera','radiolaria','diatoms','diptera','orchidaceae'];
const popularity=id=>{let at=familiarOrder.indexOf(id);return at<0?1000:at};
// Taxa documented within the chosen geological interval only; inferred approximate taxon spans
// are used for additional v4 profiles, while older curated associations are retained.
function linkedTaxa(){
 const n=nodes[selected];let base=[];
 let ctx=n;
 while(ctx){if(ctx.id==='earth'&&n.id!=='earth')break;if(ctx.taxa&&ctx.taxa.length){base=ctx.taxa.filter(id=>T[id]);break;}ctx=nodes[ctx.parent];}
 const additional=V4_TAXA.filter(t=>n.start>=t.last&&n.end<=t.first).map(t=>t.id);
 return [...new Set([...base,...additional])].filter(id=>T[id]).sort((a,b)=>popularity(a)-popularity(b)||T[a].name.localeCompare(T[b].name));
}
